  ["Administración enseña cómo va la conexión, con una prueba de mensajes."] = "Управление показывает, как идёт связь, с проверкой сообщений.",
  ["Administración: al cambiar de idioma ya no sale «Una acción de interfaz ha fallado por culpa de un accesorio». El juego no deja que un accesorio recargue la interfaz: escribe /reload."] = "Управление: при смене языка больше не появляется «Действие интерфейса не выполнено из-за модификации». Игра не позволяет аддону перезагружать интерфейс: введи /reload.",
  ["Ahora no"] = "Не сейчас",
  ["Ahora no hay nadie más de la hermandad conectado. Cuando haya alguien, sale aquí; si tiene BlazonGuild, con «Retar»."] = "Сейчас больше никого из гильдии нет в сети. Когда кто-то появится, он будет здесь; с BlazonGuild — с кнопкой «Вызвать».",
  ["Ahora no puede"] = "Сейчас не может",
  ["Ahora organizas en %s"] = "Теперь ты организуешь в %s",
  ["Ahora pulsa dónde va %s: un grupo, «Sin grupo» o «Reserva». Si pulsas a otro jugador, se cambian el sitio."] = "Теперь нажми, куда пойдёт %s: группа, «Без группы» или «Резерв». Если нажмёшь на другого игрока, они поменяются местами.",
  ["Ahora tienen %s conectados, %s con BlazonGuild."] = "Сейчас у них в сети %s, %s с BlazonGuild.",
  ["Ahora: %d %s y %d %s."] = "Сейчас: %d %s и %d %s.",
  ["Ajustes del maestro"] = "Настройки главы",
  ["Al abrir el mapa del mundo la ventana se minimiza sola, y vuelve al cerrarlo."] = "Когда ты открываешь карту мира, окно сворачивается само и возвращается, когда ты её закрываешь.",
  ["Al hablar con un posadero, un aviso te propone una partida. Todo por puntos: aquí no se mueve oro."] = "Когда ты говоришь с трактирщиком, уведомление предлагает партию. Всё на очки: здесь золото не двигается.",
  ["Al sortear, los mejores de la Arena son cabezas de serie; el resto se sortea con /roll, que veréis en el chat."] = "При жеребьёвке лучшие Арены сеяные; остальных разыгрывают через /roll, который вы увидите в чате.",
  ["Al terminar, quien la dirigió escribe cómo fue. Queda en la crónica de la hermandad con quién estuvo."] = "В конце руководитель пишет, как всё прошло. Это остаётся в летописи гильдии вместе с участниками.",
  ["Al terminar, quien la dirigió escribe el parte, que queda en la crónica."] = "В конце руководитель пишет отчёт, который остаётся в летописи.",
  ["Alguien"] = "Кто-то",
  ["Alianza"] = "Альянс",
  ["Alianza creada"] = "Альянс создан",
  ["Alianza «%s»"] = "Альянс «%s»",
  ["Alianza, pestaña «Cartas y avisos»: cartas del líder a los maestros (con quién las ha leído), «puertas abiertas» para mandar a los nuevos a una hermandad y ocultar a alguien en los chats comunes."] = "Альянс, вкладка «Письма и объявления»: письма лидера главам (с тем, кто прочитал), «открытые двери», чтобы отправлять новичков в одну гильдию, и скрытие кого-то в общих чатах.",
