  ["Así funciona la Sala de guerra"] = "Как работает Военный штаб",
  ["Así funciona la Tesorería"] = "Как работает Казна",
  ["Así funciona «Se busca»"] = "Как работает «Розыск»",
  ["Así funcionan las Raids"] = "Как работают рейды",
  ["Así funcionan los honores"] = "Как работают почести",
  ["Así tu hermandad te ve en la Armería aunque estéis lejos: lo que llevas puesto y su nivel, lo mismo que ve quien te inspecciona en el juego."] = "Так гильдия видит тебя в Оружейной даже издалека: что на тебе надето и его уровень — то же, что видит любой, кто осматривает тебя в игре.",
  ["Ausente"] = "Отсутствует",
  ["Automático (el del juego)"] = "Автоматически (язык игры)",
  ["Autoprueba"] = "Самопроверка",
  ["Autoprueba (Administración o /bg autoprueba): comprueba el addon en tu juego y te da un informe para copiar."] = "Самопроверка («Администрирование» или /bg autoprueba): проверяет аддон в твоей игре и даёт отчёт для копирования.",
  ["Avisamos a %s. En cuanto contesten, estaréis dentro."] = "Мы известили %s. Как только они ответят, вы будете внутри.",
  ["Avisamos a todos los llamados de que no se hace."] = "Мы сообщим всем вызванным, что это отменяется.",
  ["Aviso final"] = "Последнее предупреждение",
  ["Avisos %s"] = "Предупреждения %s",
  ["Avisos acumulados: %s de 3. Al tercero se abre un caso que decide el maestro."] = "Накоплено предупреждений: %s из 3. На третьем открывается дело, которое решает глава.",
  ["Avistamiento: %s"] = "Наблюдение: %s",
  ["Avistamientos"] = "Наблюдения",
  ["Ayuda"] = "Помощь",
  ["Azshara"] = "Азшара",
  ["Añade antes algún combate."] = "Сначала добавь какой-нибудь бой.",
  ["Añadir"] = "Добавить",
  ["Añadir combate"] = "Добавить бой",
  ["Añadir un combate a la velada"] = "Добавить бой в вечер",
  ["Aún nadie"] = "Пока никого",
  ["Aún nadie ha cazado a un buscado."] = "Пока никто не поймал разыскиваемого.",
  ["Aún nadie ha jugado una partida entre miembros. Las de práctica contra la casa no cuentan."] = "Пока никто не сыграл партию между участниками. Тренировки против заведения не считаются.",
  ["Aún nadie ha votado. "] = "Пока никто не проголосовал. ",
  ["Aún nadie, aparte del jefe."] = "Пока никого, кроме командира.",
  ["Aún nadie."] = "Пока никого.",
  ["Aún nadie. Cuando alguien entra, dice quién le trajo."] = "Пока никого. Кто вступает, говорит, кто его привёл.",
  ["Aún ninguna. Aquí salen las raids de BlazonGuild que ya empezaron, con cuántos fueron."] = "Пока ни одного. Здесь появляются уже начавшиеся рейды BlazonGuild и сколько человек пошло.",
  ["Aún ninguno. Cuando la hermandad mate a un jefe de esta banda (con la mayoría del grupo de la hermandad), el addon de quien estaba allí lo apunta solo."] = "Пока ни одного. Когда гильдия убьёт босса этого рейда (в группе в основном из гильдии), аддон того, кто там был, запишет это сам.",
  ["Aún no compartes tu equipo. Pulsa «Compartir mi equipo» y tu hermandad verá lo que llevas puesto (se actualiza solo cuando cambias algo)."] = "Ты пока не делишься снаряжением. Нажми «Делиться моим снаряжением», и гильдия увидит, что на тебе надето (обновляется само, когда ты что-то меняешь).",
  ["Aún no conocéis ninguna hermandad. Cuando alguien de la vuestra juegue en grupo con alguien de otra hermandad que use BlazonGuild y publique sus cifras, aparecerá aquí."] = "Вы пока не знаете ни одной гильдии. Когда кто-то из вашей сыграет в группе с кем-то из другой гильдии, которая пользуется BlazonGuild и публикует свои цифры, она появится здесь.",
  ["Aún no conocéis otras hermandades. Aparecen al jugar en grupo (mazmorras, bandas, campos de batalla) con alguien de ellas que use BlazonGuild."] = "Вы пока не знаете других гильдий. Они появляются, когда вы играете в группе (подземелья, рейды, поля боя) с кем-то из них, у кого есть BlazonGuild.",
  ["Aún no ha pasado nada. Aquí sale cada muerte y cada baja que apuntan los miembros con el addon."] = "Пока ничего не произошло. Здесь появляется каждая смерть и каждое убийство, которые записывают участники с аддоном.",
  ["Aún no ha peleado esta temporada."] = "В этом сезоне ещё не сражался.",
  ["Aún no ha respondido nadie."] = "Пока никто не ответил.",
  ["Aún no has preguntado nada."] = "Ты ещё ничего не спрашивал.",
  ["Aún no hay campeón: el primero que gane un duelo se lleva el cinturón."] = "Чемпиона пока нет: первый, кто выиграет дуэль, получает пояс.",
  ["Aún no hay cartas. El líder de la alianza escribe aquí a los maestros (y, si quiere, a los capitanes)."] = "Писем пока нет. Лидер альянса пишет здесь главам гильдий (и, если хочет, капитанам).",
  ["Aún no hay combates esta temporada."] = "В этом сезоне ещё нет боёв.",
  ["Aún no hay combates esta temporada. Reta a alguien en «Retos», o batíos en duelo desde el juego: el addon de quien pierde lo apunta solo."] = "В этом сезоне ещё нет боёв. Вызови кого-нибудь во «Вызовах» или сразитесь на дуэли в игре: аддон проигравшего запишет это сам.",
  ["Aún no hay combates.%s"] = "Пока нет боёв.%s",
  ["Aún no hay escuadras. "] = "Пока нет отрядов. ",
  ["Aún no hay escuadras. Crea una con un jefe y unos pocos miembros: tendrá su propio chat y podréis llamarla a operaciones."] = "Пока нет отрядов. Создай отряд с командиром и несколькими участниками: у него будет свой чат, и вы сможете вызывать его на операции.",
  ["Aún no hay escuadras. Las crean los organizadores; cada una tiene su jefe y su propio chat."] = "Пока нет отрядов. Их создают организаторы; у каждого свой командир и свой чат.",
  ["Aún no hay ficha. La escriben los oficiales: a qué os dedicáis, idioma, días de banda y a quién buscáis."] = "Анкеты пока нет. Её пишут офицеры: чем вы занимаетесь, язык, дни рейдов и кого ищете.",
  ["Aún no hay foto del banco. Aparecerá cuando un oficial o un tesorero lo abra con BlazonGuild."] = "Снимка банка пока нет. Он появится, когда офицер или казначей откроет банк с BlazonGuild.",
  ["Aún no hay nadie en este ranking."] = "В этом рейтинге пока никого.",
  ["Aún no hay nadie. Para salir aquí, cada uno abre la ventana de su profesión en el juego y dice «Publicar». Escribe arriba un objeto para buscar quién lo fabrica."] = "Пока никого. Чтобы появиться здесь, каждый открывает в игре окно своей профессии и нажимает «Опубликовать». Введи предмет сверху, чтобы найти, кто его делает.",
  ["Aún no hay ningún cargo."] = "Пока нет ни одной должности.",
  ["Aún no hay partes. Quien dirige una operación lo escribe al terminarla."] = "Отчётов пока нет. Руководитель операции пишет его по её окончании.",
  ["Aún no hay tesoreros: los nombra el maestro en «Cuotas». "] = "Казначеев пока нет: их назначает глава во «Взносах». ",
  ["Aún no hay torneos. Cualquiera puede crear uno con «Nuevo»: un torneo con cuadro eliminatorio, o una velada con combates anunciados."] = "Турниров пока нет. Любой может создать турнир кнопкой «Новый»: турнир на выбывание или вечер с объявленными боями.",
  ["Aún no hemos visto ninguna. En el juego, abre la ventana de tu profesión (por ejemplo, Herrería o Alquimia): BlazonGuild te preguntará si quieres publicarla. Solo la ve tu hermandad."] = "Мы ещё ни одной не видели. В игре открой окно своей профессии (например, Кузнечное дело или Алхимию): BlazonGuild спросит, хочешь ли ты её опубликовать. Видит только твоя гильдия.",
  ["Aún no se sabe qué lleva."] = "Пока неизвестно, что на нём надето.",
  ["Aún no tienes boletos hoy."] = "У тебя сегодня ещё нет билетов.",
  ["Aún no tienes honores. Cazar buscados, donar, fabricar encargos, traer gente o ir a las raids te sube en los rankings."] = "У тебя пока нет почестей. Охота на разыскиваемых, пожертвования, заказы, приглашённые игроки или рейды поднимают тебя в рейтингах.",
  ["Aún sin combates esta temporada."] = "В этом сезоне ещё нет боёв.",
  ["Aún sin contacto: llegará cuando se conecte alguien suyo con BlazonGuild."] = "Пока без связи: она появится, когда кто-то из них зайдёт с BlazonGuild.",
