  ["Las marcas sobre las placas de nombre y el aro del retrato del objetivo"] = "Метки над табличками и кольцо на портрете цели",
  ["Las mazmorras de dentro de una capital son de su bando; las demás, para todos (las Minas de la Muerte y el Castillo de Colmillo Oscuro ya salen a las dos facciones)."] = "Подземелья внутри столицы принадлежат её фракции, остальные — для всех (Мертвые копи и Крепость Темного Клыка теперь видны обеим фракциям).",
  ["Las mazmorras y bandas son ya las de WoW Forever: sus 9 mazmorras nuevas (Salón de los Feudales, Ruinas de Lordaeron, Ciudad de Dalaran, Bastión Faucenegra…) y sus tres bandas, Cavernas del Túmulo, Cima Hyjal y Guarida de Onyxia, con los nombres del juego."] = "Подземелья и рейды теперь из WoW Forever: 9 новых подземелий (Hall of Thanes, Руины Лордерона, City of Dalaran, Blackmaw Hold…) и три рейда — The Barrow Deeps, Вершина Хиджала и Логово Ониксии, с названиями из игры.",
  ["Las otras hermandades aún no han dicho cuántos van."] = "Другие гильдии ещё не сообщили, сколько идёт.",
  ["Las otras hermandades no te verán conectado. Los mensajes de «Maestros» de otras hermandades no te llegarán mientras sigas oculto."] = "Другие гильдии не увидят тебя в сети. Сообщения «Главы» других гильдий не будут доходить, пока ты скрыт.",
  ["Las otras hermandades vuelven a verte conectado."] = "Другие гильдии снова видят тебя в сети.",
  ["Las próximas dos semanas"] = "Следующие две недели",
  ["Las próximas dos semanas (%s)"] = "Следующие две недели (%s)",
  ["Las raids se comparten entre los addons de tu hermandad. Para crearlas, verlas y apuntarte, acepta antes la privacidad."] = "Рейды передаются между аддонами твоей гильдии. Чтобы создавать их, видеть и записываться, сначала прими конфиденциальность.",
  ["Las salas de roles y el comercio se comparten con todas."] = "Комнаты ролей и торговля общие для всех.",
  ["Le hemos preguntado si lo comparte; esperando su respuesta."] = "Мы спросили, поделится ли он; ждём ответа.",
  ["Le toca a %s%s"] = "Ходит %s%s",
  ["Le toca a %s…"] = "Ходит %s…",
  ["Levantar bandera"] = "Поднять флаг",
  ["Libro"] = "Книга",
  ["Libro de la tesorería"] = "Книга казны",
  ["Libro para todos: %s"] = "Книга для всех: %s",
  ["Liderazgo"] = "Руководство",
  ["Llamada a los oficiales"] = "Созыв офицеров",
  ["Llamar a los oficiales"] = "Созвать офицеров",
  ["Llegó a través de %s. «Invitar» manda la invitación del juego; «No» se lo dice con educación."] = "Пришло через %s. «Пригласить» отправляет приглашение игры; «Нет» вежливо сообщает об отказе.",
  ["Lleva un tabardo."] = "Носит гербовую накидку.",
  ["Lo apuntó el addon de %s, que perdió: solo quien pierde apunta el combate, para que nadie se dé victorias."] = "Записал аддон %s, который проиграл: бой записывает только проигравший, чтобы никто не приписывал себе побед.",
  ["Lo comparte él mismo (%s)."] = "Делится сам (%s).",
  ["Lo comparte: ya lo ves aunque esté lejos."] = "Он делится: ты видишь снаряжение даже издалека.",
  ["Lo comparten al momento quienes tienen el addon; del resto llega desde la web a través de la app puente."] = "Те, у кого есть аддон, делятся этим сразу; для остальных это приходит с сайта через приложение-мост.",
  ["Lo comparten los miembros con el addon; del resto, Battle.net a través de la web."] = "Делятся участники с аддоном; для остальных — Battle.net через сайт.",
  ["Lo decide el maestro. Ahora: %s"] = "Решает глава. Сейчас: %s",
  ["Lo decide su primer duelo: clic derecho en el retrato del otro, «Duelo»."] = "Решает их первая дуэль: правый клик по портрету другого, «Дуэль».",
  ["Lo hace %s."] = "Делает %s.",
  ["Lo hago"] = "Сделаю",
  ["Lo lleva %s"] = "У %s",
  ["Lo pide %s. %s%s"] = "Заказал %s. %s%s",
  ["Lo puedes cambiar cuando quieras en la Armería."] = "Это можно изменить в любой момент в Оружейной.",
  ["Lo puedes quitar cuando quieras en la Armería («Compartir mi equipo»)."] = "Это можно отключить в любой момент в Оружейной («Делиться снаряжением»).",
  ["Lo que dice cualquiera en el chat de hermandad, tenga o no el addon. Lo que se dijo mientras no estabas te lo pasa un compañero con BlazonGuild."] = "То, что пишет кто угодно в чате гильдии, с аддоном или без. То, что говорили, пока тебя не было, передаст соратник с BlazonGuild.",
  ["Lo que el propio juego dice de ti y cuenta para la hermandad: tus duelos con compañeros, quién te mata en JcJ fuera de mazmorras, el oro que das a un tesorero y los jefes que matáis juntos."] = "То, что сама игра сообщает о тебе и что важно для гильдии: твои дуэли с соратниками, кто убивает тебя в PvP вне подземелий, золото, которое ты отдаёшь казначею, и боссы, которых вы убиваете вместе.",
  ["Lo que la hermandad debe saber"] = "Что гильдии нужно знать",
  ["Lo que publicas lo ve tu hermandad: quién sabe hacer cada objeto, para susurrarte o hacerte un encargo. Se actualiza al abrir la profesión."] = "То, что ты публикуешь, видит твоя гильдия: кто умеет делать каждый предмет, чтобы шепнуть тебе или сделать заказ. Обновляется при открытии профессии.",
  ["Lo que responde aquí"] = "Что отвечает здесь",
  ["Lo que tu hermandad publique desde el juego podrá verse también en la web de BlazonGuild."] = "То, что твоя гильдия публикует из игры, можно будет увидеть и на сайте BlazonGuild.",
  ["Lo que tú hagas desde el addon: apuntarte a una raid, publicar un grupo, tu perfil… Cada cosa la decides tú en el momento."] = "То, что ты делаешь в аддоне: запись в рейд, публикация группы, твой профиль… Каждую вещь ты решаешь сам в тот момент.",
  ["Lo verás en la Armería en un momento."] = "Скоро увидишь в Оружейной.",
  ["Lo verás todo en /bg."] = "Всё увидишь в /bg.",
  ["Lo vio el propio cliente de %s (el resumen de muerte del juego)."] = "Это видел собственный клиент %s (сводка смерти в игре).",
  ["Lo viste tú (%s)."] = "Ты видел это (%s).",
  ["Lo último"] = "Последнее",
  ["Lo último: %s"] = "Последнее: %s",
  ["Logros"] = "Достижения",
  ["Los Baldíos"] = "Степи",
  ["Los Humedales"] = "Болотина",
  ["Los apuntados la verán como cancelada. Se puede volver a programar editándola."] = "Записавшиеся увидят его отменённым. Его можно перенести, отредактировав.",
  ["Los cambios de la alianza van firmados: nadie puede falsificarlos."] = "Изменения альянса подписаны: никто не может их подделать.",
  ["Los capitanes leen y escriben en «Oficiales de la alianza»; los mensajeros llevan los mensajes a las otras hermandades. Escribe su nombre y elige el cargo."] = "Капитаны читают и пишут в «Офицеры альянса»; гонцы передают сообщения другим гильдиям. Введи имя и выбери должность.",
  ["Los casos de moderación y los avisos ya solo están en el ordenador de los organizadores."] = "Дела модерации и предупреждения теперь хранятся только на компьютерах организаторов.",
  ["Los combates de antes siguen guardados, pero ya no cuentan."] = "Прежние бои сохраняются, но больше не считаются.",
  ["Los conectados de cada zona, tengan o no BlazonGuild."] = "Кто в сети в каждой зоне, с BlazonGuild или без.",
  ["Los enlaces de objetos del chat se ven bien (antes salían rotos), también los ya guardados."] = "Ссылки на предметы в чате отображаются правильно (раньше были сломаны), в том числе сохранённые.",
  ["Los grupos"] = "Группы",
  ["Los grupos se comparten entre los addons de tu hermandad. Acepta la privacidad para verlos (/bg privacidad)."] = "Группы передаются между аддонами твоей гильдии. Прими конфиденциальность, чтобы их видеть (/bg privacidad).",
  ["Los jefes de las bandas se apuntan aunque el juego dé solo el nombre, y la clasificación de hermandades ya verifica las fichas de las demás."] = "Боссы рейдов записываются, даже если игра даёт только имя, и рейтинг гильдий теперь проверяет карточки других гильдий.",
  ["Los mueven el líder de la raid, quien la creó y los oficiales. Tú lo ves tal como está."] = "Их перемещают лидер рейда, его создатель и офицеры. Ты видишь всё как есть.",
  ["Los nombres y lo que escribe cada uno (notas, anuncios, mensajes) salen tal cual, sin traducir."] = "Имена и то, что пишет каждый (заметки, объявления, сообщения), показываются как есть, без перевода.",
  ["Los oficiales apuntan a quién se dio cada objeto y por qué, para que la próxima banda empiece de lo ya decidido. Sin pujas ni oro."] = "Офицеры записывают, кому достался каждый предмет и почему, чтобы следующий рейд начинал с уже решённого. Без ставок и золота.",
  ["Los oficiales crean escuadras pequeñas con su jefe (por ejemplo «Los Lobos», de asalto). El jefe elige a su gente; la escuadra tiene su propio chat."] = "Офицеры создают небольшие отряды со своим командиром (например, «Волки», штурмовой). Командир выбирает людей; у отряда свой чат.",
  ["Los oficiales de %s ya la ven. Te invitarán desde el juego si dicen que sí."] = "Офицеры %s уже это видят. Они пригласят тебя из игры, если согласятся.",
  ["Los oficiales escriben la ficha pública: a qué os dedicáis, idioma, cuándo jugáis y a quién buscáis (por ejemplo, sanadores)."] = "Офицеры пишут публичную анкету: чем вы занимаетесь, язык, когда играете и кого ищете (например, лекарей).",
  ["Los organizadores de todas las hermandades de la alianza. Nadie más lo lee."] = "Организаторы всех гильдий альянса. Больше никто это не читает.",
  ["Los organizadores nombran árbitros en la Arena. Un árbitro puede decidir a mano los combates de cualquier torneo y quitar un duelo apuntado por error."] = "Организаторы назначают судей на Арене. Судья может вручную решать бои любого турнира и убирать ошибочно записанную дуэль.",
  ["Los organizadores pueden ver el addon como un miembro («Ver como miembro»), y otros addons pueden leer BlazonGuild si tú les das permiso."] = "Организаторы могут смотреть аддон как участник («Смотреть как участник»), а другие аддоны могут читать BlazonGuild, если ты разрешишь.",
  ["Los puntos de los compañeros en el mapa del mundo"] = "Точки соратников на карте мира",
  ["Los puntos del minimapa y la flecha «Seguir»"] = "Точки миникарты и стрелка «Следовать»",
  ["Los que guardas valen %d."] = "Отложенные стоят %d.",
  ["Los rankings"] = "Рейтинги",
  ["Los tesoreros"] = "Казначеи",
  ["Lotería de práctica"] = "Тренировочная лотерея",
  ["Lotería de práctica: cada día, hasta 3 boletos gratis; un oficial sortea con /roll 1-100 y se anuncia quién acierta."] = "Тренировочная лотерея: каждый день до 3 бесплатных билетов; офицер разыгрывает через /roll 1-100, и объявляют, кто угадал.",
  ["Lotería: ha salido el %s"] = "Лотерея: выпало %s",
