  ["Luchador 2"] = "Боец 2",
  ["Lugar: «%s»"] = "Место: «%s»",
  ["Líder: %s, maestro de %s."] = "Лидер: %s, глава %s.",
  ["Maestro: %s. Aún sin contacto: llegará cuando se conecte alguien suyo con BlazonGuild."] = "Глава: %s. Пока без связи: она появится, когда кто-то из них зайдёт с BlazonGuild.",
  ["Maestros"] = "Главы",
  ["Mago"] = "Маг",
  ["Mano derecha"] = "Правая рука",
  ["Mano izquierda"] = "Левая рука",
  ["Manos"] = "Кисти рук",
  ["Mapa"] = "Карта",
  ["Mapa explica qué pasa al compartir tu posición, quién te ve y dónde, y abre el mapa del mundo."] = "Карта объясняет, что происходит, когда ты делишься местоположением, кто тебя видит и где, и открывает карту мира.",
  ["Mapa, pestaña «Avistamientos»: pregunta a tu hermandad dónde se vio a un jugador de la otra facción (responde quien lo acepta)."] = "Карта, вкладка «Наблюдения»: спроси гильдию, где видели игрока другой фракции (отвечают те, кто согласился).",
  ["Mapa, pestaña «En el mapa»: «Seguir» pone una flecha bajo el minimapa que te lleva hasta un compañero o hasta el punto de reunión."] = "Карта, вкладка «На карте»: «Следовать» ставит под миникартой стрелку, которая ведёт к соратнику или к точке сбора.",
  ["Mapa: quien comparte su posición sale ahora también como un punto en tu minimapa."] = "Карта: кто делится местоположением, теперь виден и точкой на твоей миникарте.",
  ["Maraudon"] = "Мародон",
  ["Marcar leída"] = "Отметить прочитанным",
