  ["Mensaje borrado por la moderación"] = "Сообщение удалено модерацией",
  ["Mensaje del día: %s"] = "Сообщение дня: %s",
  ["Mensajero"] = "Посланник",
  ["Mensajero de la hermandad"] = "Посланник гильдии",
  ["Mensajeros: %s."] = "Посланники: %s.",
  ["Mensajes"] = "Сообщения",
  ["Mensajes de esta sesión"] = "Сообщения этого сеанса",
  ["Mensajes firmados del líder de la alianza para los maestros (y, si quiere, los capitanes). Salen en Alianza, pestaña «Cartas y avisos»; al marcarlas como leídas, el líder lo ve."] = "Подписанные сообщения лидера альянса для глав (и, если он хочет, капитанов). Видны в «Альянсе», вкладка «Письма и объявления»; когда отмечаешь их прочитанными, лидер это видит.",
  ["Mensajes por la hermandad"] = "Сообщения через гильдию",
  ["Mensajes procesados"] = "Обработанные сообщения",
  ["Mi ficha"] = "Моя анкета",
  ["Miembros"] = "Участники",
  ["Miembros con el addon conectados hace poco."] = "Участники с аддоном, недавно бывшие в сети.",
  ["Miembros en el nivel máximo."] = "Участники на максимальном уровне.",
  ["Miembros nuevos que dicen que los trajo (180 días)."] = "Новые участники, которые говорят, что их привёл он (180 дней).",
  ["Miembros que publican sus profesiones."] = "Участники, публикующие свои профессии.",
  ["Miembros que se han conectado en los últimos 7 días."] = "Участники, заходившие за последние 7 дней.",
  ["Miembros: %s (jefe)%s."] = "Участники: %s (командир)%s.",
  ["Mientras tanto ya funcionan en vivo: Resumen, La hermandad, Raids, Mazmorras y Calendario."] = "Тем временем уже работают в реальном времени: Сводка, Гильдия, Рейды, Подземелья и Календарь.",
  ["Minas de la Muerte"] = "Мертвые копи",
  ["Minimizada en %s"] = "Свёрнуто в %s",
  ["Minimizar"] = "Свернуть",
  ["Misiones"] = "Задания",
  ["Misiones en grupo"] = "Групповые задания",
  ["Moderación"] = "Модерация",
  ["Moderación para los organizadores, con avisos y casos que decide el maestro."] = "Модерация для организаторов, с предупреждениями и делами, которые решает глава.",
  ["Moderar"] = "Модерировать",
  ["Moderar a %s"] = "Модерировать %s",
  ["Modo capturas"] = "Режим скриншотов",
  ["Modo capturas (/bg capturas, o «Capturas» en Administración): una hermandad de ejemplo con nombres inventados, solo en tu pantalla, para enseñar BlazonGuild con todas las pantallas llenas. No sale nada de tu juego."] = "Режим скриншотов (/bg capturas или «Скриншоты» в Управлении): пример гильдии с вымышленными именами только на твоём экране, чтобы показать BlazonGuild со всеми заполненными экранами. Ничего не уходит из игры.",
  ["Modo capturas: una hermandad de ejemplo"] = "Режим скриншотов: пример гильдии",
  ["Modo mando"] = "Режим геймпада",
  ["Monasterio Escarlata"] = "Монастырь Алого ордена",
  ["Montaña Roca Negra"] = "Черная гора",
  ["Montañas de Alterac"] = "Альтеракские горы",
  ["Monte Hyjal"] = "Хиджал",
  ["Mostrar a tu hermandad qué personajes son tuyos"] = "Показать гильдии, какие персонажи твои",
  ["Mostrarlos"] = "Показать их",
  ["Mostrarme conectado"] = "Показывать меня в сети",
  ["Muertes con honor y actividad JcJ de cada miembro y por clase."] = "Почётные победы и PvP-активность каждого участника и по классам.",
  ["Muertes que ha causado: %s%s. Última víctima: %s."] = "Смертей на его счету: %s%s. Последняя жертва: %s.",
  ["Muñecas"] = "Запястья",
  ["Más tarde"] = "Позже",
  ["Nada"] = "Ничего",
  ["Nada en las próximas dos semanas: ni raids de BlazonGuild ni eventos en el calendario del juego. Las raids que cree cualquier miembro en Raids aparecerán aquí."] = "Ничего в ближайшие две недели: ни рейдов BlazonGuild, ни событий в календаре игры. Рейды, которые создаст любой участник в «Рейдах», появятся здесь.",
  ["Nadie"] = "Никто",
  ["Nadie (acepta la privacidad para aparecer)"] = "Никто (прими конфиденциальность, чтобы появиться)",
  ["Nadie ahora. Las peticiones las ven los oficiales."] = "Сейчас никого. Заявки видят офицеры.",
  ["Nadie ahora. Las peticiones llegan mientras estás conectado; «Invitar» manda la invitación del juego."] = "Сейчас никого. Заявки приходят, пока ты в сети; «Пригласить» отправляет приглашение игры.",
  ["Nadie coincide con la búsqueda."] = "Никто не подходит под поиск.",
  ["Nadie comparte ahora su posición. Cada uno lo enciende con «Compartir mi posición»."] = "Сейчас никто не делится местоположением. Каждый включает это кнопкой «Делиться моим местоположением».",
  ["Nadie con recompensa. Cuando alguien de la otra facción mate a un miembro fuera de mazmorras, aparecerá aquí por sí solo."] = "Ни у кого нет награды. Когда кто-то из другой фракции убьёт участника вне подземелий, он появится здесь сам.",
  ["Nadie conectado ahora mismo."] = "Сейчас никого нет в сети.",
  ["Nadie de la hermandad se llama así. Borra lo escrito para ver a todos."] = "В гильдии нет такого имени. Сотри введённое, чтобы увидеть всех.",
  ["Nadie de la lista sabe hacer «%s». En «Encargos» puedes pedirlo a quien sepa."] = "Никто в списке не умеет делать «%s». Во «Заказах» можно попросить того, кто умеет.",
  ["Nadie de «%s» conectado ahora, o el nombre no es exacto."] = "Сейчас никого из «%s» нет в сети, или название неточное.",
  ["Nadie elegido"] = "Никто не выбран",
  ["Nadie en la hermandad."] = "В гильдии никого.",
  ["Nadie en reserva."] = "В резерве никого.",
  ["Nadie ha escrito aquí todavía. Empieza tú: lo leerán con BlazonGuild las hermandades de este canal."] = "Здесь ещё никто не писал. Начни сам: гильдии этого канала прочтут это с BlazonGuild.",
  ["Nadie ha escrito aquí todavía. Empieza tú: lo leerán los miembros con BlazonGuild."] = "Здесь ещё никто не писал. Начни сам: участники с BlazonGuild прочтут это.",
  ["Nadie ha levantado bandera. Levanta la tuya arriba y la hermandad sabrá que buscas grupo."] = "Никто не поднял флаг. Подними свой сверху, и гильдия узнает, что ты ищешь группу.",
  ["Nadie lo ha visto todavía."] = "Пока никто не видел.",
  ["Nadie lo tenía."] = "Ни у кого его не было.",
  ["Nadie lo tenía. Mañana, más boletos gratis."] = "Ни у кого его не было. Завтра — новые бесплатные билеты.",
  ["Nadie más conectado ahora mismo."] = "Больше никого нет в сети.",
  ["Nadie más de la hermandad está conectado ahora."] = "Сейчас больше никто из гильдии не в сети.",
  ["Nadie más está conectado ahora."] = "Больше никого нет в сети сейчас.",
  ["Nadie te ha retado ahora. Cuando alguien lo haga, te sale aquí con «Aceptar» y «No».\n\nCómo se reta: pulsa «Retar» junto a alguien de la lista (tiene que estar conectado y con BlazonGuild). Si acepta, os avisamos a los dos.\n\nEl duelo lo empezáis desde el juego (clic derecho en su retrato, «Duelo»). Retar no es obligatorio: cualquier duelo entre dos de la hermandad con BlazonGuild cuenta."] = "Сейчас тебя никто не вызвал. Когда кто-то вызовет, это появится здесь с кнопками «Принять» и «Нет».\n\nКак вызвать: нажми «Вызвать» рядом с кем-то из списка (он должен быть в сети и с BlazonGuild). Если он примет, мы сообщим вам обоим.\n\nДуэль вы начинаете в игре (правый клик по портрету, «Дуэль»). Вызывать не обязательно: любая дуэль между двумя участниками гильдии с BlazonGuild засчитывается.",
  ["Nadie tiene puntos apuntados."] = "Ни у кого нет записанных очков.",
  ["Nadie todavía"] = "Пока никого",
  ["Nadie. El líder puede ocultar a un jugador o a una hermandad en los chats comunes durante un tiempo."] = "Никого. Лидер может на время скрыть игрока или гильдию в общих чатах.",
  ["Naxxramas"] = "Наксрамас",
  ["Necesitas estar en una hermandad."] = "Тебе нужно состоять в гильдии.",
  ["Ninguna"] = "Нет",
  ["Ninguna encuesta abierta. Cualquiera puede preguntar a la hermandad: qué banda hacer, a qué hora quedar…"] = "Нет открытых опросов. Любой может спросить гильдию: какой рейд пройти, во сколько собраться…",
  ["Ninguna. Cuando otra hermandad os invite, aparecerá aquí y vuestro maestro decidirá."] = "Нет. Когда другая гильдия пригласит вас, это появится здесь, и ваш глава решит.",
  ["Ninguno"] = "Нет",
  ["Ninguno en esta versión"] = "Нет в этой версии",
  ["Ningún botón se sale de su panel: ahora lo comprueban las pruebas en todas las pantallas."] = "Ни одна кнопка не выходит за свою панель: теперь тесты проверяют это на всех экранах.",
  ["Ningún organizador con BlazonGuild está conectado ahora. Prueba más tarde."] = "Сейчас нет в сети ни одного организатора с BlazonGuild. Попробуй позже.",
  ["Nivel"] = "Уровень",
  ["Nivel %d"] = "Уровень %d",
  ["Nivel %d %s, %s"] = "Уровень %d %s, %s",
