  ["Nivel mínimo"] = "Минимальный уровень",
  ["Nivel y logros en vivo del juego; equipo y JcJ, de los miembros con el addon y de la web."] = "Уровень и достижения — из игры в реальном времени; снаряжение и PvP — от участников с аддоном и с сайта.",
  ["Niveles en vivo del juego y raids de BlazonGuild."] = "Уровни из игры в реальном времени и рейды BlazonGuild.",
  ["Niveles en vivo del juego; los grupos se comparten entre los miembros con el addon y con la web."] = "Уровни из игры в реальном времени; группы передаются между участниками с аддоном и сайтом.",
  ["No"] = "Нет",
  ["No aceptar peticiones de capa"] = "Не принимать просьбы о слое",
  ["No compartes tu posición."] = "Ты не делишься местоположением.",
  ["No cuenta para la Arena: %s no tiene BlazonGuild (el combate lo apunta el addon de quien pierde)."] = "Не засчитывается на Арене: у %s нет BlazonGuild (бой записывает аддон проигравшего).",
  ["No cuenta para la Arena: no es de tu hermandad."] = "Не засчитывается на Арене: он не из твоей гильдии.",
  ["No es de tu hermandad."] = "Он не из твоей гильдии.",
  ["No es tu turno."] = "Сейчас не твой ход.",
  ["No está conectado"] = "Не в сети",
  ["No está en tu hermandad"] = "Не в твоей гильдии",
  ["No estáis en ninguna alianza."] = "Вы не состоите ни в одном альянсе.",
  ["No estás en ninguna hermandad."] = "Ты не состоишь ни в одной гильдии.",
  ["No hay campañas. Una campaña junta oro para algo concreto (por ejemplo, 100 de oro para pociones de banda) y enseña cuánto falta."] = "Кампаний нет. Кампания собирает золото на что-то конкретное (например, 100 золотых на рейдовые зелья) и показывает, сколько осталось.",
  ["No hay cuota semanal. %s"] = "Еженедельного взноса нет. %s",
  ["No hay encargos. Pide un objeto a un artesano (o a quien sepa hacerlo): te avisamos cuando lo tome y cuando esté hecho."] = "Заказов нет. Попроси предмет у ремесленника (или у того, кто умеет его делать): мы сообщим, когда он возьмётся и когда будет готово.",
  ["No hay grupos abiertos ahora. Crea uno y tu hermandad podrá apuntarse por rol desde el juego."] = "Сейчас нет открытых групп. Создай свою, и гильдия сможет записаться по ролям из игры.",
  ["No hay nada que elegir ahora."] = "Сейчас выбирать нечего.",
  ["No hay operaciones planeadas."] = "Операций не запланировано.",
  ["No hay operaciones. Las planean los organizadores y los jefes de escuadra; cuando haya una, te avisamos y respondes desde aquí."] = "Операций нет. Их планируют организаторы и командиры отрядов; когда появится операция, мы сообщим, и ты ответишь отсюда.",
  ["No hay operaciones. Planea una: qué se hace, cuándo, dónde y qué escuadras van. Cada uno responde «Voy», «Reserva» o «No puedo»."] = "Операций нет. Запланируй одну: что, когда, где и какие отряды идут. Каждый отвечает «Иду», «Резерв» или «Не могу».",
  ["No hay sitio"] = "Нет мест",
  ["No llegaste a la capa de %s. Puedes intentarlo de nuevo."] = "Ты не попал в слой %s. Можно попробовать ещё раз.",
  ["No lleva tabardo."] = "Не носит гербовую накидку.",
  ["No lo comparte. Pulsa «Ver su equipo»: si está cerca, lo inspeccionas; si está lejos y tiene BlazonGuild, se lo pedimos.%s"] = "Он не делится. Нажми «Смотреть снаряжение»: если он рядом — осмотришь; если далеко и у него есть BlazonGuild — мы его попросим.%s",
  ["No lo comparte. Si lo tienes cerca (tu objetivo, el ratón encima o en tu grupo), pulsa «Inspeccionar»: lo verás tú, sin enviarlo a nadie.%s"] = "Не делится. Если он рядом (твоя цель, под курсором или в твоей группе), нажми «Осмотреть»: увидишь только ты, ничего никуда не отправится.%s",
  ["No molestar"] = "Не беспокоить",
