  ["Nota (opcional)"] = "Заметка (необязательно)",
  ["Nota de la hermandad: %s"] = "Заметка гильдии: %s",
  ["Nota para la hermandad (opcional)"] = "Заметка для гильдии (необязательно)",
  ["Nota para quien lo lea (opcional)"] = "Заметка для читателя (необязательно)",
  ["Nota: %s"] = "Заметка: %s",
  ["Notas de botín"] = "Заметки о добыче",
  ["Notas de botín para los organizadores (a quién se dio qué y por qué), con puntos opcionales a mano. Sin pujas ni oro."] = "Заметки о добыче для организаторов (кому что досталось и почему), с необязательными очками вручную. Без ставок и золота.",
  ["Novedades de BlazonGuild %s"] = "Что нового в BlazonGuild %s",
  ["Nueva Armería: el equipo de cada uno, ranura a ranura, si lo comparte (pulsa «Compartir mi equipo»), o si lo inspeccionas tú de cerca."] = "Новая Оружейная: снаряжение каждого, ячейка за ячейкой, если он делится (нажми «Делиться моим снаряжением»), или если ты осмотришь его вблизи.",
  ["Nueva Sala de guerra: escuadras con su jefe y su propio chat."] = "Новый Военный штаб: отряды со своим командиром и чатом.",
  ["Nueva campaña"] = "Новая кампания",
  ["Nueva clave"] = "Новый ключ",
  ["Nueva clave para la alianza"] = "Новый ключ для альянса",
  ["Nueva escuadra"] = "Новый отряд",
  ["Nueva hermandad hermana"] = "Новая гильдия-сестра",
  ["Nueva operación"] = "Новая операция",
  ["Nueva raid"] = "Новый рейд",
  ["Nueva raid: %s"] = "Новый рейд: %s",
  ["Nueva sala"] = "Новая комната",
  ["Nueva sección Alianza: une tu hermandad con otras (lo deciden los maestros)."] = "Новый раздел «Альянс»: объедини свою гильдию с другими (решают главы).",
  ["Nueva sección Arena: duelos entre miembros con su clasificación. El resultado lo lee el propio juego."] = "Новый раздел «Арена»: дуэли между участниками с рейтингом. Результат читает сама игра.",
  ["Nueva sección Artesanía y botín: al abrir tu profesión, puedes publicarla para tu hermandad."] = "Новый раздел «Ремёсла и добыча»: открыв свою профессию, ты можешь опубликовать её для гильдии.",
  ["Nueva sección Chat: el chat de hermandad con más espacio y salas como Sanadores o Comercio."] = "Новый раздел «Чат»: чат гильдии с большим простором и комнатами вроде «Лекари» или «Торговля».",
  ["Nueva sección Mapa: cuántos compañeros hay en cada zona y quiénes son."] = "Новый раздел «Карта»: сколько соратников в каждой зоне и кто они.",
  ["Nueva sección Reclutamiento: la ficha pública de la hermandad, que escriben los oficiales."] = "Новый раздел «Набор»: публичная анкета гильдии, которую пишут офицеры.",
  ["Nueva sección Tablón: anuncios, encuestas, turnos de palabra, la crónica y el resumen de la semana."] = "Новый раздел «Доска»: объявления, опросы, очередь слова, летопись и сводка недели.",
  ["Nueva sección Tesorería: el libro de la hermandad se apunta solo cuando das oro a un tesorero (comercio o correo)."] = "Новый раздел «Казна»: книга гильдии заполняется сама, когда ты отдаёшь золото казначею (обменом или почтой).",
  ["Nueva sección «Se busca»: quien de la otra facción mate a uno de los vuestros fuera de mazmorras entra en la lista con su recompensa."] = "Новый раздел «Розыск»: кто из другой фракции убьёт одного из ваших вне подземелий, попадает в список со своей наградой.",
  ["Nueva temporada"] = "Новый сезон",
  ["Nuevo"] = "Новый",
  ["Nuevo JcE: quién tiene nivel para cada banda, los jefes que lleva derrotados la hermandad (se apuntan solos) y las últimas raids."] = "Новый PvE: у кого есть уровень для каждого рейда, побеждённые гильдией боссы (записываются сами) и последние рейды.",
  ["Nuevo anuncio"] = "Новое объявление",
  ["Nuevo botón redondo en el minimapa: un clic abre o cierra BlazonGuild; arrástralo para moverlo."] = "Новая круглая кнопка на миникарте: один клик открывает или закрывает BlazonGuild; перетащи её, чтобы передвинуть.",
  ["Nuevo botón «?» arriba: «Cómo funciona», una guía corta y con ejemplos de cada sección complicada."] = "Новая кнопка «?» сверху: «Как это работает» — короткое руководство с примерами для каждого сложного раздела.",
  ["Nuevo encargo"] = "Новый заказ",
  ["Nuevo honor en Rankings: Campeón de la Arena. Y arreglado: algunos botones salían sin texto."] = "Новая почесть в «Рейтингах»: Чемпион Арены. И исправлено: некоторые кнопки были без текста.",
  ["Nuevo líder de la alianza"] = "Новый лидер альянса",
  ["Nuevo torneo o velada"] = "Новый турнир или вечер",
  ["Nunca se comparten tu BattleTag ni tu posición en el mapa sin que lo aceptes aparte, una cosa cada vez. Si no aceptas, el addon te sigue mostrando tu hermandad, pero no envía nada."] = "Твой BattleTag и твоё местоположение на карте никогда не передаются, пока ты не примешь это отдельно, по одному. Если не примешь, аддон всё равно показывает тебе гильдию, но ничего не отправляет.",
  ["Nunca se comparten tu posición en el mapa, tu equipo, tus otros personajes, tu BattleTag ni dónde ves a enemigos sin que lo aceptes aparte, una cosa cada vez. Si no aceptas, el addon te sigue mostrando tu hermandad, pero no envía nada."] = "Твоё место на карте, снаряжение, другие персонажи, BattleTag и где ты видишь врагов никогда не передаются без отдельного согласия, по одному. Если не согласишься, аддон по-прежнему показывает твою гильдию, но ничего не отправляет.",
  ["Nunca se han enfrentado"] = "Ещё не встречались",
  ["Núcleo de Magma"] = "Огненные Недра",
  ["Núcleo de Magma, Guarida Alanegra, Zul'Gurub, Ahn'Qiraj y Naxxramas ya no salen para elegir: no están en Forever. Una raid antigua que las usara se sigue viendo."] = "Огненные Недра, Логово Крыла Тьмы, Зул'Гуруб, Ан'Кираж и Наксрамас больше не предлагаются: их нет в Forever. Старый рейд с ними по-прежнему виден.",
  ["O elígelo de la lista"] = "Или выбери из списка",
