  ["|c%s|Hbgline:%s:%s|h%s|h|r"] = "|c%s|Hbgline:%s:%s|h%s|h|r",
  ["¡%s gana el torneo!"] = "%s выигрывает турнир!",
  ["¡%s gana «%s»!"] = "%s выигрывает «%s»!",
  ["¡A las armas!"] = "К оружию!",
