  ["¡En marcha!"] = "Начинаем!",
  ["¡Ganas a los Huesos!"] = "Ты выиграл в Кости!",
  ["¡Has ganado la partida!"] = "Ты выиграл партию!",
  ["¡Has ganado!"] = "Ты победил!",
  ["¡Hola! Te saludo desde BlazonGuild."] = "Привет! Приветствую из BlazonGuild.",
  ["¡Huesos! %s pierde %d puntos."] = "Кости! %s теряет %d очков.",
  ["¡Huesos! Pierdes %d puntos."] = "Кости! Ты теряешь %d очков.",
  ["¡Le ganas a la casa!"] = "Ты обыграл заведение!",
  ["¡Los seis guardados! Se tiran todos otra vez."] = "Все шесть отложены! Бросаем все заново.",
  ["¡Operación en marcha!"] = "Операция началась!",
  ["¡Ya sois hermanas!"] = "Теперь вы сёстры!",
  ["«%s» no es de tu hermandad."] = "«%s» не из твоей гильдии.",
  ["«%s» puede leer BlazonGuild."] = "«%s» может читать BlazonGuild.",
  ["«%s» quiere leer BlazonGuild"] = "«%s» хочет читать BlazonGuild",
  ["«%s» ya existe. Ahora invita a otra hermandad."] = "«%s» уже существует. Теперь пригласи другую гильдию.",
  ["«%s» ya no puede leer BlazonGuild."] = "«%s» больше не может читать BlazonGuild.",
  ["«%s», %s. El parte queda en la crónica de la hermandad."] = "«%s», %s. Отчёт остаётся в летописи гильдии.",
  ["«%s»: %s hermandades, en contacto con %s"] = "«%s»: гильдий %s, на связи с %s",
  ["«Cara a cara» pone a dos luchadores uno frente al otro, con su vida en directo si los tienes cerca y quién gana al acabar. Se puede agrandar para retransmitir."] = "«Лицом к лицу» ставит двух бойцов друг против друга, с их здоровьем вживую, если они рядом, и победителем в конце. Можно увеличить для трансляции.",
  ["«Colocar en la banda» mueve a la gente a sus grupos de verdad cuando la banda ya está formada (líder o ayudante, fuera de combate)."] = "«Расставить в рейде» переводит людей в их настоящие группы, когда рейд уже собран (лидер или помощник, вне боя).",
  ["«Copiar» y luego Ctrl+C: pégalo donde quieras."] = "«Копировать», затем Ctrl+C: вставь куда угодно.",
  ["«Grupos» enseña los grupos de la banda como en el juego. El líder de la raid, quien la creó y los oficiales arrastran a cada uno a su grupo y su fila (o lo pulsan y luego pulsan dónde va)."] = "«Группы» показывает группы рейда, как в игре. Лидер рейда, его создатель и офицеры перетаскивают каждого в его группу и строку (или нажимают на него, а затем туда, куда он идёт).",
  ["«Invitar confirmados» invita a los que van y están conectados, y convierte el grupo en banda."] = "«Пригласить подтвердивших» приглашает тех, кто идёт и в сети, и превращает группу в рейд.",
  ["«Mazmorras» ahora se llama Grupos: también para JcJ, misiones, subir de nivel o farmear."] = "«Подземелья» теперь называются «Группы»: также для PvP, заданий, прокачки или фарма.",
  ["«Retar» le manda tu reto; el duelo lo empezáis desde el juego."] = "«Вызвать» отправляет ему твой вызов; дуэль вы начинаете в игре.",
  ["«Se busca»"] = "«Розыск»",
  ["«Ver su ficha» en el menú del botón derecho del juego"] = "«Смотреть анкету» в меню правого клика игры",
  ["«Ver un duelo» (o /bg duelo): el cara a cara del duelo de tu objetivo. Y en cada torneo o velada, «Cara a cara del siguiente combate»."] = "«Смотреть дуэль» (или /bg duelo): «лицом к лицу» для дуэли твоей цели. А в каждом турнире или вечере боёв — «Следующий бой: лицом к лицу».",
